INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (4, 1, 3001, 10, 1, 7, 8, 10, "vo_minigame_1012_result_1000", "フフ、全問正解よ！\nちゃんと勉強してるみたいで\n感心だわ♪", 1, 3.18, 11300101);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (10, 1, 3001, 10, 1, 8, 7, 10, "vo_minigame_1012_result_1001", "すごいじゃない…全問正解よ！\nま、当然といや当然よね～\nだってあたしが\n教えてやってんだから♪", 1, 3.33, 11300102);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (10, 1, 3001, 10, 1, 8, 1, 10, "vo_minigame_1012_result_1002", "全問正解！　パチパチパチ～♪\nこの難易度はもう完璧じゃない？\n次はもっと難しい問題に挑戦よ！\nあんたならできるって！", 1, 5.41, 11300103);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (10, 1, 3001, 10, 2, 5, 8, 10, "vo_minigame_1012_result_1003", "へえ…難しい問題を選んだのに\n全問正解できてるじゃない！！\nちょっとあんたすごすぎだわ…！\nパーフェクトよパーフェクト！", 1, 8.11, 11300104);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 10, 2, 10, 5, 10, "vo_minigame_1012_result_1004", "まる…まる…全部まる！\n難しい問題なのに全問正解よ…！\n驚いた…あんたいつの間に、\nこんなに勉強してたのよ！", 1, 1.31, 11300105);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 10, 2, 9, 8, 10, "vo_minigame_1012_result_1005", "ここまで完璧に正解されちゃうと\nちょっと悔しいわね…！\nけど素直に褒めてやるわ！\nえらい、えらい、えら～い！", 1, 4.93, 11300106);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (4, 1, 3001, 10, 3, 5, 8, 10, "vo_minigame_1012_result_1006", "すごい…あんたパーフェクトよ！\nこのままいけば次の試験、\n学年一位も夢じゃないかもね！\n楽しみだわ～♪", 1, 2.99, 11300107);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (4, 1, 3001, 10, 3, 8, 7, 10, "vo_minigame_1012_result_1007", "満点よ！　フフ、もうあんたに\n教えることはなにもないわ…！\n逆にあたしがあんたに教わりたい\nくらいよ！　…ね、先生♪", 1, 8.37, 11300108);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (8, 1, 3001, 10, 3, 7, 5, 10, "vo_minigame_1012_result_1008", "全・問・正・解！\n超難問揃いなのにすごいわね…！\nもしかしてだけど、\nあんたって天才！？", 1, 5.32, 11300109);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (4, 1, 3001, 7, 1, 7, 1, 9, "vo_minigame_1012_result_1009", "お、かなりいい点数ね～！\nあたしも教えがいがあるわ♪\nさ、まだまだ勉強するわよ！", 1, 4.77, 11300110);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (4, 1, 3001, 7, 1, 8, 7, 9, "vo_minigame_1012_result_1010", "うん、いい感じで点取れてるわ！\nこの調子で次は、\n満点を見せてほしいわね！", 1, 2.97, 11300111);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 7, 1, 5, 1, 9, "vo_minigame_1012_result_1011", "あ～惜しい！\nもうちょっとで満点じゃない！\n次はパーフェクトいけるわ！\n頑張りましょ！", 1, 3.47, 11300112);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (4, 1, 3001, 7, 2, 8, 7, 9, "vo_minigame_1012_result_1012", "すごい、かなりできてるわよ！\n難しい問題なのにやるじゃない！\nあとは目指せ、満点ね！", 1, 5.32, 11300113);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (10, 1, 3001, 7, 2, 8, 7, 9, "vo_minigame_1012_result_1013", "うん、かなりいい感じよ！\nあんたには赤点の心配なんて\nまーったくなさそうね♪\nでも勉強はやめさせないけど！", 1, 6.49, 11300114);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 7, 2, 5, 1, 9, "vo_minigame_1012_result_1014", "あーあとちょっとで\n全問正解だったのに！\n難しい問題だけどあんたなら\n次は満点狙えるわ！", 1, 3.56, 11300115);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (10, 1, 3001, 7, 3, 8, 1, 9, "vo_minigame_1012_result_1015", "うん、ほとんど正解よ！\nこんな難しい問題なのに、\nすごいじゃない！\nやっぱりあんた只者じゃないわ！", 1, 5.67, 11300116);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (10, 1, 3001, 7, 3, 7, 1, 9, "vo_minigame_1012_result_1016", "着実に成長してるって感じね？\nあんたならこの難問でも、\nいつか満点取れちゃうかも…！", 1, 2.85, 11300117);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 7, 3, 5, 1, 9, "vo_minigame_1012_result_1017", "うわー惜しいわね！\nもうちょっとで満点よ？\nま、あたしでも悩む難問だから、\nこの点数は胸を張っていいわ！", 1, 3.88, 11300118);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 4, 1, 3, 1, 6, "vo_minigame_1012_result_1018", "正解率は半分くらいか～\n悪くはないんだけど、あんたなら\nこんなもんじゃないでしょ？", 1, 4.12, 11300119);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 4, 1, 9, 1, 6, "vo_minigame_1012_result_1019", "んーはっきり言っちゃうと\n中途半端な点数ね…\nまあいいわ！こっからガンガン\n点数上げていくわよ！", 1, 4.34, 11300120);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 4, 1, 3, 1, 6, "vo_minigame_1012_result_1020", "う～ん、正直物足りない点数ね！\nあんたには期待してんだから、\nもっと頑張んなさい！", 1, 3.15, 11300121);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 4, 2, 9, 1, 6, "vo_minigame_1012_result_1021", "半分くらいの正解率か\n難しい問題だから仕方ないわね…\nでもあんたはもっとできる！\nだってあたしがついてんのよ！", 1, 5.3, 11300122);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 4, 2, 8, 1, 6, "vo_minigame_1012_result_1022", "うん、そこそこできんじゃない！\n頑張って勉強して\nさらに上を目指しましょ！", 1, 2.55, 11300123);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 4, 2, 1, 7, 6, "vo_minigame_1012_result_1023", "難問なのにこの正解率は\nよくやってる方よね！\nでもこんなところで\n満足してんじゃないわよ！？", 1, 4.19, 11300124);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 4, 3, 7, 1, 6, "vo_minigame_1012_result_1024", "難問なのに半分くらい正解\nできてんじゃない♪\nこの調子でもっと学力\n上げていきましょ！", 1, 3.43, 11300125);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 4, 3, 1, 1, 6, "vo_minigame_1012_result_1025", "よし、平均点ってとこね！\nちゃんと勉強してるみたいで\n安心したわ～♪", 1, 0, 11300126);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 4, 3, 8, 7, 6, "vo_minigame_1012_result_1026", "難問揃いでこの正解率は\n大したもんよ！\nま、もっといい点取りたいんなら\n勉強、付き合ったげるわ！", 1, 3.72, 11300127);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (1, 1, 3001, 1, 1, 3, 2, 3, "vo_minigame_1012_result_1027", "なるほど…\nこれは教えがいがあるわね\nビシバシ鍛えてやるから\n覚悟しなさい！", 1, 3.5, 11300128);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (1, 1, 3001, 1, 1, 4, 2, 3, "vo_minigame_1012_result_1028", "ちょっとあんた、\n全然できてないじゃない！\n…まさかこれが本気だなんて\n言わないわよね～？", 1, 3.25, 11300129);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 1, 1, 3, 2, 3, "vo_minigame_1012_result_1029", "うーん……適当に答えても\nこれくらい正解できるわよ？\nちょっと本腰入れて\n教えないとね……！", 1, 4.62, 11300130);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 1, 2, 9, 1, 3, "vo_minigame_1012_result_1030", "…ま、まあこの問題は\nあんたには難しすぎたのかもね\nちょっとずつでいいから、\nレベルアップしていきましょ！", 1, 4.5, 11300131);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (9, 1, 3001, 1, 2, 3, 3, 3, "vo_minigame_1012_result_1031", "んー結構ミスっちゃってるわね…\nこのまま続けるのもいいけど、\n簡単な問題からやり直すのも\nありかもよ～？", 1, 0.01, 11300132);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (9, 1, 3001, 1, 2, 9, 9, 3, "vo_minigame_1012_result_1032", "あらら、あんたにはちょっと\n難しすぎたかしら…？\nもう一回やり直しましょうか！", 1, 0.01, 11300133);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (6, 1, 3001, 1, 3, 3, 3, 3, "vo_minigame_1012_result_1033", "うーん、残念な結果ね…\n超難問だから仕方ないけど\n無理せず簡単な問題から挑戦\nしてもいいかもよ？", 1, 0.01, 11300134);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 1, 3, 3, 9, 3, "vo_minigame_1012_result_1034", "正解率はかなり悪いわね…\nまあ難しい問題だもんね…！\nそのチャレンジ精神は買うわ！", 1, 2.97, 11300135);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 1, 3, 3, 1, 3, "vo_minigame_1012_result_1035", "なんとか０点は免れたわね…\n難問揃いだけど、\nもっと頑張っていきましょ！", 1, 3.1, 11300136);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (1, 1, 3001, 0, 1, 6, 2, 0, "vo_minigame_1012_result_1036", "…あんたさ、０点なんて\n逆に取るの難しいわよ！？\nまさか狙ったわけじゃ\nないでしょーね～！？", 1, 4.31, 11300137);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (1, 1, 3001, 0, 1, 2, 2, 0, "vo_minigame_1012_result_1037", "０点って…\nあんたふざけてんの！？\nちゃんとやらないなら\n電撃魔法くらわせるわよ！？", 1, 0.1, 11300138);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (9, 1, 3001, 0, 1, 9, 3, 0, "vo_minigame_1012_result_1038", "もしかしたらあんたは\n勉強向いてないのかもね…\n…勉強だけがすべてじゃないわ\n違うとこで頑張りましょ！", 1, 4.23, 11300139);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 0, 2, 3, 2, 0, "vo_minigame_1012_result_1039", "怒んないから正直に言って？\n…ふざけて答えたでしょ？\nほら、正直に\n言・い・な・さ・い？", 1, 4.38, 11300140);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 0, 2, 8, 2, 0, "vo_minigame_1012_result_1040", "あんたの点数は～～…\n…はい！　０てーん！！\n…って、ふざけんなーー！！！", 1, 3.58, 11300141);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (1, 1, 3001, 0, 2, 4, 2, 0, "vo_minigame_1012_result_1041", "０点ってどういうこと！？\nいやあんた、逆にすごいわよ！？\n目つぶってやったとしても\n１点は取れるから！", 1, 2.02, 11300142);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (9, 1, 3001, 0, 3, 9, 1, 0, "vo_minigame_1012_result_1042", "あちゃー……残念だけど０点よ\nちょっと難しすぎたかもねー…\n…ま、こんなこともあるわ！\n気を落とさなくていいわよ！", 1, 5.53, 11300143);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (9, 1, 3001, 0, 3, 3, 1, 0, "vo_minigame_1012_result_1043", "かなりの難問とはいえ、\n０点はちょっと寂しいわね…\nでもま、逆に考えるのよ！\nあんたには伸びしろしかないわ！", 1, 4.4, 11300144);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 0, 3, 3, 1, 0, "vo_minigame_1012_result_1044", "０点かー…うん、ごめん…\n慰めの言葉が浮かばないわ！\n……ま、次があるから\n切り替えてくのよ！", 1, 5.35, 11300145);
