INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (10, 2, 3001, 20, 1, 7, 1, -1, "vo_minigame_1012_result_1045", "はい、よくできました！\n基礎はもう完璧ね！\n次はもっと難しい問題にも\nチャレンジしちゃいなさいよ！", 1, 3.74, 12300101);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 20, 1, 1, 9, -1, "vo_minigame_1012_result_1046", "なによあんた、走り出したペンが\n止まらないって感じ？\nったくシンプルにすごいじゃない\n花丸あげるわ！", 1, 3.85, 12300102);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (8, 2, 3001, 20, 1, 5, 5, -1, "vo_minigame_1012_result_1047", "すごい点数ね…！\nあんた勉強してないとか言って\nホントはめちゃくちゃやってる\nパターンのやつね！？", 1, 0.01, 12300103);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (4, 2, 3001, 20, 2, 8, 7, -1, "vo_minigame_1012_result_1048", "勉強の成果、\nちゃんとでてんじゃない！\nあたしもあんたの先生として、\n鼻が高いわ～♪", 1, 2.86, 12300104);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (9, 2, 3001, 20, 2, 5, 3, -1, "vo_minigame_1012_result_1049", "オッケー！　もう十分よ！\nこれ以上でき過ぎちゃったら、\nあたしが教える必要なくなるわ！", 1, 2.02, 12300105);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 20, 2, 5, 1, -1, "vo_minigame_1012_result_1050", "難しい問題を選んだつもりなのに\nすごい正解数ね…！\nでもまだ上がある…\n次は最難関に挑戦よ！", 1, 4.46, 12300106);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (7, 2, 3001, 20, 3, 5, 4, -1, "vo_minigame_1012_result_1051", "すごいすごいとは思ってたけど、\nあんた勉強も完璧なの…？\nそりゃみんなあんたに惚れ…\nや、な、なんでもない！！", 1, 6.85, 12300107);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 20, 3, 5, 9, -1, "vo_minigame_1012_result_1052", "この問題、あたしでも悩む\n超難問なのに…\nふふっ、もう褒めるしかないわ！\n大変よくできました！", 1, 3.79, 12300108);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (7, 2, 3001, 20, 3, 4, 4, -1, "vo_minigame_1012_result_1053", "別に顔赤くなんてなってない！\n頭がいい人が好きとか…\nかっこいいとか…\n…思ってないからね！", 1, 0.01, 12300109);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 20, 1, 5, 5, -1, "vo_minigame_1012_result_1054", "スピードも正確さも完璧…\n文句なしの満点だわ！\nあんた将来、とんでもない人に\nなっちゃうんじゃない！？", 1, 0, 12300110);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 20, 2, 5, 5, -1, "vo_minigame_1012_result_1054", "スピードも正確さも完璧…\n文句なしの満点だわ！\nあんた将来、とんでもない人に\nなっちゃうんじゃない！？", 1, 0, 12300112);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 20, 3, 5, 5, -1, "vo_minigame_1012_result_1054", "スピードも正確さも完璧…\n文句なしの満点だわ！\nあんた将来、とんでもない人に\nなっちゃうんじゃない！？", 1, 0, 12300114);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (10, 2, 3001, 15, 1, 5, 7, 19, "vo_minigame_1012_result_1056", "おお～かなり正解できてるわね！\nこの調子でもっとすごい点\n目指しちゃうわよ！", 1, 3, 12300116);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (10, 2, 3001, 15, 1, 8, 8, 19, "vo_minigame_1012_result_1057", "うん、バッチリいい感じよ！\nちゃんと勉強してるみたいで\n関心関心♪", 1, 0.01, 12300117);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 15, 1, 5, 8, 19, "vo_minigame_1012_result_1058", "え、こんなにいい点取れたのに\nまだ満足してないの？\nなによその向上心…\nいいじゃない！", 1, 4.01, 12300118);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (10, 2, 3001, 15, 2, 8, 7, 19, "vo_minigame_1012_result_1059", "スピードも正解数もいい感じよ！\nねえねえ、この調子で\nてっぺん目指しちゃう？", 1, 2.83, 12300119);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 15, 2, 10, 10, 19, "vo_minigame_1012_result_1060", "この難易度でも\nスラスラ答えちゃうなんて…\nあんたって\nほんとすごいやつよね…！", 1, 0, 12300120);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (4, 2, 3001, 15, 2, 8, 7, 19, "vo_minigame_1012_result_1061", "これだけ正解できたら\n勉強も楽しいわよね♪\nさ、まだまだ続けるわよ～！", 1, 3.66, 12300121);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 15, 3, 5, 8, 19, "vo_minigame_1012_result_1062", "あんた、この成績\nまぐれじゃないわよね…！\nこれだけできたら\n大したもんだわ！", 1, 3.28, 12300122);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 15, 3, 8, 1, 19, "vo_minigame_1012_result_1063", "すごい！　とってもいい成績よ！\nこの難問も、あんたにかかりゃ\nイチコロってやつ？", 1, 2.7, 12300123);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (9, 2, 3001, 15, 3, 5, 9, 19, "vo_minigame_1012_result_1064", "あんた…もしかして\nあたしより点数いいかも？\nあ、あたしもあんたを見習って\n勉強しないとね…！", 1, 3.98, 12300124);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 10, 1, 7, 1, 14, "vo_minigame_1012_result_1067", "うん、なかなかいい点数よ！\nでもまだまだ頑張れるわよね？\nはい、次いきましょ！", 1, 2.51, 12300131);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 10, 1, 1, 7, 14, "vo_minigame_1012_result_1068", "十分優秀な成績だけど\nあんたならもっとできる！\nさ、頑張って勉強するわよ！", 1, 4.16, 12300132);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 10, 1, 8, 7, 14, "vo_minigame_1012_result_1069", "うん、いい感じね！\nこの調子で少しずつ、\n正解数を増やしてくわよ！", 1, 2.07, 12300133);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 10, 2, 8, 1, 14, "vo_minigame_1012_result_1070", "難問揃いなのに、\nけっこーいい感じじゃない！\nちゃんとできてるから\n自信もっていいわよ！", 1, 3.51, 12300134);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 10, 2, 1, 1, 14, "vo_minigame_1012_result_1071", "難しい問題でも基礎は大事よ！\nこの調子でどんどん\n点数上げていきましょう！", 1, 0, 12300135);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 10, 2, 1, 7, 14, "vo_minigame_1012_result_1072", "10問以上取れてるわね！\nえ、まだ物足りない？\nフフ、じゃあもっと上\n目指しちゃう？", 1, 4.3, 12300136);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 10, 3, 8, 7, 14, "vo_minigame_1012_result_1073", "うん、この難問でこの点数は\n十分すぎる出来よね！\nま、あんたならもっといい点\n目指しちゃうんだろうけど♪", 1, 4.47, 12300137);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 10, 3, 8, 9, 14, "vo_minigame_1012_result_1074", "はいお疲れ～\nなかなか良い点数じゃない\n…あたしも勉強しないとね！", 1, 3.68, 12300138);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 10, 3, 5, 1, 14, "vo_minigame_1012_result_1075", "おお～10問以上\n正解してんじゃない！\nあんたやっぱり\nただ者じゃないわね～", 1, 3.34, 12300139);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 10, 1, 1, 8, 14, "vo_minigame_1012_result_1077", "うん正解率は申し分なしね！\nあとはもっと早く解ければ\nもっと点数は伸びてくわよ！\nこの調子で頑張っていきましょ！", 1, 6.58, 12300141);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 10, 2, 1, 8, 14, "vo_minigame_1012_result_1077", "うん正解率は申し分なしね！\nあとはもっと早く解ければ\nもっと点数は伸びてくわよ！\nこの調子で頑張っていきましょ！", 1, 6.58, 12300143);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 10, 3, 1, 8, 14, "vo_minigame_1012_result_1077", "うん正解率は申し分なしね！\nあとはもっと早く解ければ\nもっと点数は伸びてくわよ！\nこの調子で頑張っていきましょ！", 1, 6.58, 12300145);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 5, 1, 1, 7, 9, "vo_minigame_1012_result_1078", "ふ～ん、まあまあの出来だわ\n悪くはないんだけど…あんたには\nもっともっと期待してるわ～", 1, 4.24, 12300146);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 5, 1, 7, 1, 9, "vo_minigame_1012_result_1079", "うん、頑張ったけど…\n正直もっと正解できるかもね～？\nこんなのあんたには通過点！\nさらに良い点目指してみない？", 1, 4.74, 12300147);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 5, 1, 1, 1, 9, "vo_minigame_1012_result_1080", "まあまあな点数だけど、\n自分的に手ごたえはどう？\nダメだって思ってんなら、\nまだまだ伸びる余地ありね！", 1, 0, 12300148);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 5, 2, 8, 1, 9, "vo_minigame_1012_result_1081", "うん、中々の出来ね！\nでもあんたはもっといい点\n取れるはずよ！\nもっと頑張りましょうか！", 1, 2.21, 12300149);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 5, 2, 3, 1, 9, "vo_minigame_1012_result_1082", "ん～はっきり言って微妙ね！\nま、難しい問題だし、\n勉強すれば\n点数は上がっていくと思うわ！", 1, 2.46, 12300150);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 5, 2, 3, 1, 9, "vo_minigame_1012_result_1083", "ん～…\n10点には届かなかったか～\n次は10点越え目指して\n頑張ってみない？", 1, 2.94, 12300151);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 5, 3, 7, 1, 9, "vo_minigame_1012_result_1084", "はいお疲れ～\n点数的にはまあまあってとこね！\nま、超難問だし頑張ったわよ", 1, 4.19, 12300152);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 5, 3, 1, 1, 9, "vo_minigame_1012_result_1085", "うん、かなり難しい問題なのに\n最後までやり遂げたわね\n次はもっといい点目指してみる？", 1, 0, 12300153);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 5, 3, 3, 1, 9, "vo_minigame_1012_result_1086", "ちょっとミスが多かったかもね～\nでも間違えた所は復習して\n次は正解するわよー！", 1, 2.63, 12300154);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 1, 1, 3, 1, 4, "vo_minigame_1012_result_1087", "あら…あんまり良くない点数ね～\nどうしたの、調子でも悪かった？\n次はもっと頑張りましょうか", 1, 5.53, 12300155);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (9, 2, 3001, 1, 1, 3, 3, 4, "vo_minigame_1012_result_1088", "ん～…正解数は\n物足りないわね～\nもうちょっと勉強の時間\n増やしちゃおっか？", 1, 0.01, 12300156);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (3, 2, 3001, 1, 1, 3, 1, 4, "vo_minigame_1012_result_1089", "ん～…あんたならもうちょと\nいい点取れんでしょ～？\nもっと頑張んなさいよ\n期待してやってんだからさ！", 1, 4.15, 12300157);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (9, 2, 3001, 1, 2, 9, 9, 4, "vo_minigame_1012_result_1090", "ん～今のあんたには、\nこの問題は難しかったかしら…\n難易度下げてチャレンジするのも\nありかもね～？", 1, 0.01, 12300158);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 1, 2, 3, 1, 4, "vo_minigame_1012_result_1091", "あんまり出来は良くないわね～\n難しい問題だししょうがないけど\n次はもっと頑張ってほしいわ！", 1, 5.37, 12300159);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 1, 2, 3, 1, 4, "vo_minigame_1012_result_1092", "なるほど…\nちょっと苦手な問題が多かった？\nもう一度チャレンジ\nしてみましょうか～", 1, 1.44, 12300160);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 1, 3, 3, 3, 4, "vo_minigame_1012_result_1093", "んん～…問題が難しすぎた？\n無理に難しい問題続けるより、\n難易度下げた方が\n勉強の効率良いかもよ～？", 1, 0, 12300161);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (3, 2, 3001, 1, 3, 3, 9, 4, "vo_minigame_1012_result_1094", "…あんまり点数取れなかったわね\nこれはあたしにも難しい問題だし\nそう落ち込まなくても大丈夫！\n次頑張りましょ！", 1, 2.91, 12300162);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 1, 3, 5, 1, 4, "vo_minigame_1012_result_1095", "ごめん、ちょっと難しすぎた？\nもう一度チャレンジするも良し、\n難易度を下げるも良し、\nあんたがやる気なら付き合うわ！", 1, 2.61, 12300163);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (1, 2, 3001, 0, 1, 4, 2, 0, "vo_minigame_1012_result_1096", "ちょっとあんた…\nやる気ないわよね～！？\n次こんな点数取ったら\n怒るわよ！", 1, 3.63, 12300164);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (1, 2, 3001, 0, 1, 6, 2, 0, "vo_minigame_1012_result_1097", "はあ…自分で何点取ったか\n分かってるわよね～…？\n０点よ０点！　舐めてんの！？", 1, 4.16, 12300165);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (6, 2, 3001, 0, 1, 3, 3, 0, "vo_minigame_1012_result_1098", "うう～頭痛い…\nあんたのせいよ！\nなに０点って！\nはあ、このままじゃ赤点よ～…", 1, 0.01, 12300166);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 0, 2, 6, 2, 0, "vo_minigame_1012_result_1099", "ねえ、あんた本気でやったの？\nまさか適当にやるわけないわよね\n…分かった、\nもう一回チャレンジするのよ！", 1, 5.75, 12300167);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (1, 2, 3001, 0, 2, 4, 2, 0, "vo_minigame_1012_result_1100", "あ…あんた、０点よ０点…！\nあたしの教え方が悪かった…？\n…燃えてきたわ！\n絶対あんたの学力上げてやる！", 1, 5.64, 12300168);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (8, 2, 3001, 0, 2, 8, 4, 0, "vo_minigame_1012_result_1101", "ちょっと待って採点ミスかも…\n…いや合ってるわね。はい０点\n…って０点！？\nふざけんなーー！", 1, 5.73, 12300169);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (1, 2, 3001, 0, 3, 5, 3, 0, "vo_minigame_1012_result_1102", "あらら…０点よ\nま、難しい問題だしね…\n…つっても０点は無いわ！\n一問くらい正解しなさいよ！", 1, 5.32, 12300170);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (9, 2, 3001, 0, 3, 3, 9, 0, "vo_minigame_1012_result_1103", "残念だけど０点よ\nま、まあ前向きにとらえるなら、\n今が底よ！　どん底！\nあとは上がってくだけね！", 1, 2.37, 12300171);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (3, 2, 3001, 0, 3, 9, 1, 0, "vo_minigame_1012_result_1104", "…かなり出来が悪いわね\n一旦休憩しましょうか？\nリフレッシュして頭切り替えて\nもう一度頑張りましょう！", 1, 4.25, 12300172);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 3, 1001, 0, 0, 7, 7, 0, "vo_minigame_1012_gamestart_100", "さ、勉強を始めるわよ", 1, 0, 13100101);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 3, 1001, 0, 0, 1, 1, 0, "vo_minigame_1012_gamestart_101", "よし、勉強の成果を見てやるわ！", 1, 0, 13100102);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 3, 1001, 0, 0, 1, 7, 0, "vo_minigame_1012_gamestart_102", "じゃあ試験するわよ。はい教科書閉じて！", 1, 1.82, 13100103);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (4, 3, 1002, 3, 0, 8, 8, -1, "vo_minigame_1012_gamestart_103", "やる気マンマンじゃない！", 1, 0.01, 13100201);
