INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 3, 1003, 1, 0, 0, 0, 1, "vo_minigame_1012_gamestart_105", "普通の難易度よ！", 1, 0, 13100301);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 3, 1003, 1, 0, 7, 7, 1, "vo_minigame_1012_gamestart_106", "まずは基本からね！", 1, 0, 13100302);
