INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 10, 1, 6, 0, 10, "vo_minigame_1012_result_2000", "すご、全部〇じゃん…！\nこの調子で教えてくれたら\nうちも頭よくなりそー！", 2, 3.32, 21300101);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (3, 1, 3001, 10, 1, 6, 2, 10, "vo_minigame_1012_result_2001", "え、〇しかなかった…？\n満点ってほんとにあるんだ…\nヒデサイマジすごい…！", 2, 6.5, 21300102);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (5, 1, 3001, 10, 1, 3, 6, 10, "vo_minigame_1012_result_2002", "満点じゃん！　やりー！\nもしかしてヒデサイには\n簡単過ぎた感じ？", 2, 3.1, 21300103);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (11, 1, 3001, 10, 2, 3, 2, 10, "vo_minigame_1012_result_2003", "ビシッと決まったね！\nヒデサイ、ベンキョー\n教えてくれてありがとー♪", 2, 2.06, 21300104);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 10, 2, 3, 7, 10, "vo_minigame_1012_result_2004", "ムズい問題もぜーんぶ正解！\n激アツじゃん！\nヒデサイ、頭よすぎ～", 2, 4.45, 21300105);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (11, 1, 3001, 10, 2, 2, 2, 10, "vo_minigame_1012_result_2005", "きゃはっ、満点じゃん！\n一緒にベンキョーしてる\nうちまでいい気分！", 2, 0.01, 21300106);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (11, 1, 3001, 10, 3, 2, 3, 10, "vo_minigame_1012_result_2006", "ヒデサイ、満点パーフェクト！\nこれで、もーサイツヨだね！\nそれっ、ハイタッチ～！", 2, 6.64, 21300107);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 10, 3, 6, 6, 10, "vo_minigame_1012_result_2007", "カンペキ過ぎて\nまぶしぃんですけど！\n〇しかないってどゆこと！？", 2, 0, 21300108);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 10, 3, 6, 7, 10, "vo_minigame_1012_result_2008", "おにムズでも満点じゃん…！\nヒデサイセンセーマジすごい！\nこれからも頼りにしてるよ～", 2, 5.76, 21300109);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 7, 1, 6, 6, 9, "vo_minigame_1012_result_2009", "ヒデサイ、もしかして\nよゆーな感じ？\n正解しまくりじゃん！", 2, 0, 21300110);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 7, 1, 2, 7, 9, "vo_minigame_1012_result_2010", "〇いっぱいで、わろ～\nてかヒデサイ教えるのうまっ！\nめちゃわかりやすかったよ♪", 2, 2.59, 21300111);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (11, 1, 3001, 7, 1, 2, 3, 9, "vo_minigame_1012_result_2011", "これだけ〇あったら、\nめちゃ気持ちいいね♪\n次は満点取っちゃおー！", 2, 4.09, 21300112);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 7, 2, 2, 3, 9, "vo_minigame_1012_result_2012", "満点まで、もーすぐじゃん！\nさっすがヒデサイ！\nバイブス上がってきた～", 2, 2.47, 21300113);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (11, 1, 3001, 7, 2, 3, 3, 9, "vo_minigame_1012_result_2013", "きゃはっ、めちゃ解けてる～\nもー次は満点っしょ！\nテンアゲしてきたね♪", 2, 0.01, 21300114);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 7, 2, 2, 2, 9, "vo_minigame_1012_result_2014", "ヒデサイのおかげで\nうちもちょっちベンキョー\nわかってきたかも！", 2, 0, 21300115);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 7, 3, 6, 2, 9, "vo_minigame_1012_result_2015", "おにムズ問題も\n〇ばっかじゃん…！\nヒデサイ、マジ心強い！", 2, 3.45, 21300116);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 7, 3, 3, 3, 9, "vo_minigame_1012_result_2016", "ヒデサイセンセーに\n追いつけ追い越せ！\nうちもがんばる～！", 2, 0, 21300117);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 7, 3, 2, 3, 9, "vo_minigame_1012_result_2017", "おにムズ問題も\nあとちょいで満点じゃん！\nもーここまできたら\nやるしかないっしょ！", 2, 4, 21300118);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 4, 1, 6, 0, 6, "vo_minigame_1012_result_2018", "お！　あと半分だし\nうちも、もうちっと\nがんばってみるね！", 2, 0.92, 21300119);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 4, 1, 0, 3, 6, "vo_minigame_1012_result_2019", "まだイミフな問題あるけど\n悪くないよね？\nバイブス上がってきたし\n次もっとイケんじゃない？", 2, 4.36, 21300120);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 4, 1, 6, 2, 6, "vo_minigame_1012_result_2020", "だいたい半分ぐらい？\nじゃあ、こっからだね！\n集中、集中！", 2, 2.35, 21300121);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 4, 2, 0, 2, 6, "vo_minigame_1012_result_2021", "これで半分ぐらい？\nよしっ、とりま赤点回避！\nやりー！", 2, 2.13, 21300122);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 4, 2, 0, 2, 6, "vo_minigame_1012_result_2022", "あともう半分だね！\nフレッフレッ、ヒデサイ！\nうちもがんばる～！", 2, 2.38, 21300123);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 4, 2, 4, 0, 6, "vo_minigame_1012_result_2023", "う～ん、やっぱムズいね\nでも、半分ぐらい〇だし\nイケそーな気するね！", 2, 3.5, 21300124);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 4, 3, 0, 6, 6, "vo_minigame_1012_result_2024", "だいたい半分正解？\nとゆーことは\nあと半分で満点じゃん！", 2, 2.25, 21300125);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 4, 3, 3, 6, 6, "vo_minigame_1012_result_2025", "やるじゃんヒデサイ！\nえ？　もっと上目指すの？\nじゃあうちもがんばる！", 2, 2.14, 21300126);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 4, 3, 6, 2, 6, "vo_minigame_1012_result_2026", "おにムズだったのに\n半分解けてる…！？\nヒデサイいい感じ！", 2, 3.75, 21300127);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (5, 1, 3001, 1, 1, 4, 10, 3, "vo_minigame_1012_result_2027", "おにムズだったね～\n…え？　これって簡単なの？\nえへへ、うそだ～？", 2, 2.53, 21300128);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (9, 1, 3001, 1, 1, 4, 4, 3, "vo_minigame_1012_result_2028", "…ねーねー、ヒデサイ\nうちに合わせて\n悪い点取らなくていいんだよ？", 2, 0.01, 21300129);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 1, 1, 0, 3, 3, "vo_minigame_1012_result_2029", "ウォーミングアップは\nこんなところで…\nヒデサイ、次は\n本気出しちゃおうよ！", 2, 2.93, 21300130);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (4, 1, 3001, 1, 2, 0, 3, 3, "vo_minigame_1012_result_2030", "あ、ヒデサイ\nうちと点数おそろじゃん！\n一緒に赤点取っちゃおっか～♪", 2, 4.26, 21300131);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 1, 3001, 1, 2, 10, 10, 3, "vo_minigame_1012_result_2031", "えーっと…\nもっかい教えてくれたら\n次はもうちょい\nイケる気するよっ！", 2, 0, 21300132);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (5, 1, 3001, 1, 2, 9, 0, 3, "vo_minigame_1012_result_2032", "うちもさっぱりだった～\nどこ間違えたんだろ…？\nもっかいベンキョーしてみる？", 2, 4.98, 21300133);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (9, 1, 3001, 1, 3, 4, 4, 3, "vo_minigame_1012_result_2033", "おにムズ過ぎてマジさっぱり…\nどーしよ…\nヒデサイ、助けて～", 2, 0.01, 21300134);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (6, 1, 3001, 1, 3, 4, 4, 3, "vo_minigame_1012_result_2034", "赤点って感じ？\nう～ん…せっかくだし\nうちと一緒にがんばろ！", 2, 0.01, 21300135);
