INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 10, 3, 7, 7, 14, "vo_minigame_1012_result_2073", "おにムズ問題でも教えるの\n超やさしーし、マジ感謝！\n一緒にがんばろーね♪", 2, 0, 22300137);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 10, 3, 6, 6, 14, "vo_minigame_1012_result_2074", "おにムズなのに\n〇けっこーあるし\nヒデサイすごくない？", 2, 0, 22300138);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 10, 3, 6, 5, 14, "vo_minigame_1012_result_2075", "おにムズでこのペースは\nすごいんじゃ…？\nうちもがんばってついてくね！", 2, 4.21, 22300139);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 5, 1, 0, 3, 9, "vo_minigame_1012_result_2078", "悪くないよね？\nでもでも\nヒデサイとうちなら\nもっとできる気する！", 2, 1.94, 22300146);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 5, 1, 4, 0, 9, "vo_minigame_1012_result_2079", "もっと〇ほしーね…\n地道にやるしか\nないっぽいし\nもっかい教えてくれる？", 2, 2.28, 22300147);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 5, 1, 4, 4, 9, "vo_minigame_1012_result_2080", "ベンキョーしたけど\nわかんないとこばっか…\nヒデサイセンセー、助けて～", 2, 0, 22300148);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 5, 2, 4, 3, 9, "vo_minigame_1012_result_2081", "やっぱムズかったね…\nでも次はもうちょい\nできそーな気がするよ！", 2, 2.67, 22300149);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 5, 2, 10, 6, 9, "vo_minigame_1012_result_2082", "問題ムズいし、この点数は\nありよりのありっしょ？\nえ、もっとできた感じ？", 2, 4.68, 22300150);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 5, 2, 9, 9, 9, "vo_minigame_1012_result_2083", "どこ間違ったんだろ？\nうちさっぱりだった…\nやっぱムズいだけあるね", 2, 0, 22300151);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 5, 3, 0, 3, 9, "vo_minigame_1012_result_2084", "激ムズだけど\nやることは一緒だよね？\nうちもヒデサイについてくから\nコツコツがんばろ！", 2, 3.55, 22300152);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 5, 3, 4, 6, 9, "vo_minigame_1012_result_2085", "やっぱおにムズだね…\nそだ、迷ったら\nヒント使うのも\nありよりのあり？", 2, 2.51, 22300153);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 5, 3, 9, 5, 9, "vo_minigame_1012_result_2086", "やっぱテストって\nなんとなくじゃ無理？\n覚えるしかないの？\nじゃあがんばるしかないね…", 2, 6.15, 22300154);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (6, 2, 3001, 1, 1, 4, 9, 4, "vo_minigame_1012_result_2087", "できたと思ったけど\nそーじゃなかった系？\nテストってマジきびしー…", 2, 4.12, 22300155);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (6, 2, 3001, 1, 1, 4, 4, 4, "vo_minigame_1012_result_2088", "うーん…さっぱり！\nでも簡単な問題なんだよね…？\nもっかいやってみる？", 2, 0.01, 22300156);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 1, 1, 0, 3, 4, "vo_minigame_1012_result_2089", "うちらまだまだ\nベンキョーちうだし…\nこれからだよねっ？\nね、ヒデサイ！", 2, 5.28, 22300157);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 1, 2, 0, 3, 4, "vo_minigame_1012_result_2090", "ちょっとずつ覚えれば\nおーけーっしょ！\nうちと一緒に\nベンキョーだね！", 2, 2.89, 22300158);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 1, 2, 0, 7, 4, "vo_minigame_1012_result_2091", "うちベンキョー苦手でも\nヒデサイとベンキョー\nするのは好き！　だから\nもっかい教えてくれる？", 2, 5.45, 22300159);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (3, 2, 3001, 1, 2, 4, 10, 4, "vo_minigame_1012_result_2092", "覚えても、すぐ忘れるんだけど\nどしたらいい？\nあ、そーゆうとき\nフクシューする感じ？", 2, 4.29, 22300160);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (6, 2, 3001, 1, 3, 4, 8, 4, "vo_minigame_1012_result_2093", "ムズ過ぎ！\n頭パンクするかと思った…！\nヒデサイ、うちの頭\nふぅふぅして～", 2, 4.64, 22300161);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 1, 3, 9, 5, 4, "vo_minigame_1012_result_2094", "おにムズ過ぎてテンサゲ～\nでもヒデサイがんばってるし\nうちもがんばる！", 2, 3.14, 22300162);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 1, 3, 7, 4, 4, "vo_minigame_1012_result_2095", "ヒデサイと同じ点数で\nちょっち安心したかも\n一緒にがんばろーね！\n置いてっちゃやだよ？", 2, 6.59, 22300163);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 0, 1, 3, 3, 0, "vo_minigame_1012_result_2096", "…まあ、これより下はないし\n次は大逆転\n点数爆上がりっしょ！", 2, 0, 22300164);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (5, 2, 3001, 0, 1, 9, 10, 0, "vo_minigame_1012_result_2097", "０点じゃん…\nそだ、次はえんぴつ転がして\n選ぶ作戦やってみる？", 2, 2.2, 22300165);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (6, 2, 3001, 0, 1, 4, 4, 0, "vo_minigame_1012_result_2098", "考えるの無理な時あるよね…\nヒデサイもそーゆう\n感じだったの？", 2, 0.01, 22300166);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (3, 2, 3001, 0, 2, 6, 2, 0, "vo_minigame_1012_result_2099", "え、ヒデサイも０点？\nじゃあうちと一緒じゃん♪\nまあ焦んないで\nベンキョーしてこーよ！", 2, 2.8, 22300167);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (6, 2, 3001, 0, 2, 9, 4, 0, "vo_minigame_1012_result_2100", "むむむ～…０点…！\n覚えてもすぐ忘れちゃうし\nベンキョーってマジ大変", 2, 3.22, 22300168);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (11, 2, 3001, 0, 2, 4, 0, 0, "vo_minigame_1012_result_2101", "０点だね…\nでも、へーきへーき\nリベンジしたら、結果オーライ！", 2, 2.1, 22300169);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (3, 2, 3001, 0, 3, 0, 2, 0, "vo_minigame_1012_result_2102", "おやつ休憩して\nリベンジしよっ！\n甘いの食べたら、イケるっしょ！", 2, 2.74, 22300170);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (9, 2, 3001, 0, 3, 6, 9, 0, "vo_minigame_1012_result_2103", "ヒデサイでも\nおにムズな感じ？\nじゃあ、このテスト\n誰も解けなくない？", 2, 3, 22300171);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (0, 2, 3001, 0, 3, 10, 2, 0, "vo_minigame_1012_result_2104", "…あれ？\n０が〇に見えてきた！\nきゃはっ、ちょっち\nやる気出てきたかも！", 2, 4.37, 22300172);
INSERT INTO `v1_6007a92bbc9fc1d3966127e52e33e882ef6c7ed6e2b6d0eeb6f2c1eaceb80d6f` VALUES (10, 3, 1001, 0, 0, 0, 0, 0, "vo_minigame_1012_gamestart_200", "よーし、がんばるぞー", 2, 0.01, 23100101);
